// SIMULATOR: anchors hashes of the SIMULATED readings on Polygon Amoy testnet.
// The transactions are real, but the data they record is generated by lib/simulator.js.
// Each payload carries "src":"sim" so anyone decoding the calldata can see where it came from.
import { createPublicClient, createWalletClient, http, stringToHex } from "viem";
import { privateKeyToAccount } from "viem/accounts";
import { polygonAmoy } from "viem/chains";
import { redis } from "./store";

const TX_LOG = "sim:tx";
const TX_INFO = "sim:txinfo";
const BUSY = "sim:anchor:busy";
const PERIOD = "sim:anchor:period";
const KEEP = 12;
export const MIN_INTERVAL_S = 25;
export const EXPLORER = polygonAmoy.blockExplorers.default.url;

const key = process.env.ANCHOR_PRIVATE_KEY;
const account = key ? privateKeyToAccount(key) : null;
const transport = http(process.env.AMOY_RPC_URL || undefined);
const publicClient = createPublicClient({ chain: polygonAmoy, transport });
const walletClient = account ? createWalletClient({ account, chain: polygonAmoy, transport }) : null;

export const walletAddress = account?.address ?? null;

// kind: "batch" (every ~30 s, rate-limited) or "alert" (on entering DANGER)
export async function anchor({ kind, batch, dataHash, level, count }) {
  if (!walletClient || !redis) return { error: "not configured" };
  // One send at a time (avoids nonce clashes), and batches no more than once per MIN_INTERVAL_S.
  if (kind === "batch" && !(await redis.set(PERIOD, 1, { nx: true, ex: MIN_INTERVAL_S }))) return { skipped: true };
  if (!(await redis.set(BUSY, 1, { nx: true, ex: 15 }))) return { skipped: true };

  try {
    const payload = { v: 1, src: "sim", dev: "AQ-01", kind, b: batch, n: count, lvl: level, h: dataHash, ts: Math.floor(Date.now() / 1000) };
    const hash = await walletClient.sendTransaction({ to: account.address, value: 0n, data: stringToHex(JSON.stringify(payload)) });
    const entry = { hash, kind, batch, dataHash, level, count, sentAt: Date.now() };
    await redis.pipeline().lpush(TX_LOG, JSON.stringify(entry)).ltrim(TX_LOG, 0, KEEP - 1).exec();
    return { hash };
  } catch (e) {
    return { error: e.shortMessage ?? e.message };
  } finally {
    await redis.del(BUSY);
  }
}

// Recent transactions with live confirmation status.
export async function recent() {
  if (!redis) return { txs: [], wallet: walletAddress };
  const raw = await redis.lrange(TX_LOG, 0, -1);
  const txs = raw.map((x) => (typeof x === "string" ? JSON.parse(x) : x));
  const info = (await redis.hgetall(TX_INFO)) ?? {};
  let latest = null;
  try {
    latest = await publicClient.getBlockNumber();
  } catch {}

  await Promise.all(
    txs.map(async (tx) => {
      let known = info[tx.hash];
      if (typeof known === "string") known = JSON.parse(known);
      if (!known) {
        try {
          const r = await publicClient.getTransactionReceipt({ hash: tx.hash });
          known = { block: Number(r.blockNumber), fee: Number(r.gasUsed * r.effectiveGasPrice) / 1e18, ok: r.status === "success" };
          await redis.hset(TX_INFO, { [tx.hash]: JSON.stringify(known) });
        } catch {} // not mined yet
      }
      if (known) Object.assign(tx, known, { confirmations: latest ? Number(latest) - known.block + 1 : null });
    })
  );

  let balance = null;
  try {
    if (walletAddress) balance = Number(await publicClient.getBalance({ address: walletAddress })) / 1e18;
  } catch {}
  return { txs, wallet: walletAddress, balance, latestBlock: latest ? Number(latest) : null };
}
